window.DICTIONARY_ENTRY_SHARDS["006b-0079"]={"006b-0079:2b9352c76723e3":{"word":"kyrillisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ky·ril·lisch","de-DE":"ky·ril·lisch"},"forms":[{"form":"cyrillisch","tags":["variant"]},{"form":"kyrillisch","tags":["Positiv"]},{"form":"zyrillisch","tags":["variant"]},{"form":"kyrillische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"kyrillischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"kyrillischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"kyrillischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"kyrillisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist kyrillisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist kyrillisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist kyrillisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind kyrillisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"in der Form an die griechische Unziale angelehnt und ursprünglich zur Verschriftlichung des Altkirchenslawischen entwickelt"}],"synonyms":[],"origins":["Benannt nach Kyrill von Saloniki, einem slawischen Missionar und Entwickler des ersten slawischen Alphabets (ist nicht identisch mit der heutigen kyrillischen Schrift!)"],"examples":[{"text":"„П“ ist ein kyrillisches Schriftzeichen (Buchstabe) und entspricht in lateinischer Schrift dem „P“.","reference":""},{"text":"„Bulgarisch, Russisch und Serbisch sind eng verwandt, werden aber aus historischen Gründen mit kyrillischen Buchstaben verschriftlicht.“","reference":"Steffen Möller: Expedition zu den Polen. Eine Reise mit dem Berlin-Warszawa-Express. Malik, München 2012 , Seite 220. ISBN 978-3-89029-399-8."},{"text":"„Es ist nicht zu ändern, die nächste halbe Stunde stehe ich wieder an der zugigen Durchfahrt und male fein säuberlich kyrillische Buchstaben in die kleinen, dafür vorgesehenen Felder.“","reference":"Sonya Winterberg: Wir sind die Wolfskinder. Verlassen in Ostpreußen. Piper, München/Zürich 2014, ISBN 978-3-492-30264-7, Seite 306."},{"text":"„Allein das kyrillische Alphabet, das in Bulgarien die Wegweiser und Ortschaften zur vollkommenen Unkenntlichkeit verschlüsselte, war eine Herausforderung für sich.“","reference":"Markus Maria Weber: Ein Coffee to go in Togo. Ein Fahrrad, 26 Länder und jede Menge Kaffee. 2. Auflage. Conbook Medien, Meerbusch 2016, ISBN 978-3-95889-138-8, Seite 85."}],"idioms":["Tag der kyrillischen Schrift"],"collocations":[],"derivations":["kyrillische Schrift","kyrillisches Alphabet","Kyrillisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"kyrillisch","id":"2b9352c76723e3"},"006b-0079:998dd94e2880c8":{"word":"Kybernetik","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·ber·ne·tik","de-DE":"Ky·ber·ne·tik"},"forms":[{"form":"Kybernetik","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Wissenschaft informationeller Netzwerke in dynamischen, selbstregulierenden und selbstorganisierenden Systemen"}],"synonyms":["Regelungstechnik","Steuertechnik"],"origins":["im 20. Jahrhundert entlehnt von gleichbedeutend englisch cybernetics ^(→ en) aus dem 1948 erschienenen Buch „Cybernetics or Control and Communication in the Animal and the Machine“ von dem amerikanischen Mathematiker Norbert Wiener; von griechisch κυβερνητική τέχνη (kybernētikē technē^☆) ^(→ grc) „Steuermannskunst“ zu κυβερνᾶν (kybernan^☆) ^(→ grc) „steuern, leiten“"],"examples":[{"text":"Sich selbst regulierende Systeme, und davon handelt ja die Kybernetik, gibt es in ungemein vielen Zusammenhängen. Wir finden sie zum Beispiel in der Nachrichtentheorie, der Entscheidungstheorie, der Spieltheorie und der Netzwerktheorie.","reference":""}],"idioms":[],"collocations":[],"derivations":["kybernetisch","Kybernetisierung","Kybernetiker"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Kybernetik","id":"998dd94e2880c8"},"006b-0079:152566463a6a2d":{"word":"Kyū","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Kyū","de-DE":"Kyū"},"forms":[{"form":"Kyu","tags":["alternative"]},{"form":"Kyū","tags":["Nominativ","Singular"]},{"form":"Kyūs","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Schülergrad im Budo"}],"synonyms":[],"origins":["von japanisch: 級 (kyū) entlehnt; wörtlich: Schülergrad, Rang"],"examples":[{"text":"Der Kyū ist einer der sechs Leistungsgrade, die es in den Budosportarten gibt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyū","id":"152566463a6a2d"},"006b-0079:4b1164213b2611":{"word":"Kyll","partOfSpeech":"Toponym","gender":"die","hyphenation":{"de-CH":"Kyll","de-DE":"Kyll"},"forms":[{"form":"Kyll","tags":["Nominativ","Singular"]}],"senses":[{"definition":"ein Fluss in Deutschland, Nebenfluss der Mosel"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Kyll ist der längste Fluss der Eifel.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyll","id":"4b1164213b2611"},"006b-0079:f4a56a6f3a8a45":{"word":"kymrisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"kym·risch","de-DE":"kym·risch"},"forms":[{"form":"cymr.","tags":["obsolete"]},{"form":"kymr.","tags":["Kurzform"]},{"form":"cymrisch","tags":["obsolete"]},{"form":"kymrisch","tags":["Positiv"]},{"form":"kymrische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"kymrischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"kymrischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"kymrischer","tags":["Komparativ"]},{"form":"kymrisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"kymrischere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"kymrischste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"kymrischerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"kymrischeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"kymrischerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"kymrischeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"kymrischstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"kymrischsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"kymrischster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"kymrischstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"am kymrischsten","tags":["Superlativ"]},{"form":"er ist kymrisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist kymrisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist kymrisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist kymrischer","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist kymrischer","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind kymrisch","tags":["Positiv","predicative","Plural"]},{"form":"sie ist kymrischer","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind kymrischer","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am kymrischsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am kymrischsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am kymrischsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am kymrischsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"die Sprache Kymrisch betreffend"}],"synonyms":["Walisisch"],"origins":[],"examples":[{"text":"„Sie steht in einer kymrischen Handschrift aus dem 14. Jahrhundert (Llyfr Coch Hergest), die zusammen mit einer früheren Schrift Mabinogion genannt wurde.“","reference":"Der Rebell des Gesetzes, DIE ZEIT 2000"},{"text":"„Die kymrischen Erzählungen sind ein wesentlicher Bestandteil unseres gemeinsamen europäischen Erbes.“","reference":"Medialität und mittelalterliche insulare Literatur, Band 1, Seite 170, Hildegard L. C. Tristram, Gunter Narr Verlag, 1992 ISBN 3823342584"},{"text":"„Während der Adel die englische Sprache übernahm, wurde von der unteren Bevölkerungsschicht die kymrische Sprache bis Anfang des 20. Jahrhunderts gesprochen.“","reference":"Ulrike Peters: Kelten. Ein Schnellkurs. DuMont, Köln 2011, ISBN 978-3-8321-9319-5 , Seite 81."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"kymrisch","id":"f4a56a6f3a8a45"},"006b-0079:dd7c2b3173a265":{"word":"Kymation","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ky·ma·ti·on","de-DE":"Ky·ma·ti·on"},"forms":[{"form":"Kyma","tags":["variant"]},{"form":"Kymatien","tags":["Nominativ","Plural"]},{"form":"Kymation","tags":["Nominativ","Singular"]},{"form":"Kymations","tags":["Nominativ","Plural"]}],"senses":[{"definition":"ein antikes, friesartiges Ornament in Form einer Zier- oder Schmuckleiste, das in den drei klassischen Erscheinungsformen „dorisch“, „ionisch“ und „lesbisch“ vorkommt"}],"synonyms":[],"origins":["aus altgriechisch: κυμάτιον (kymátion) wörtlich: „kleine Welle“ hier in der Bedeutung „wellenförmigen Ornamenten“; zu κῦμα (kỹma) Welle gebildet"],"examples":[{"text":"Das Kymation ist eine Schmuckleiste, die bei Architekturgliedern wie Kapitell, Fries, Architrav, dann aber auch bei Gegenständen wie Sarkophagen verwendet wurden.","reference":"nach: Heinrich Laag: Kleines Wörterbuch der frühchristlichen Kunst und Archäologie. Mit einem Anhang altgriechischer Fachwörter und 100 Abbildungen. 1. Auflage. Reclam, Stuttgart 2001, ISBN 978-3-15-008633-9 , Seite 134"},{"text":"Die frühchristliche Kunst hat die klassischen drei Formen des Dorischen, des Ionischen und des Lesbischen Kymations übernommen.","reference":"nach: Heinrich Laag: Kleines Wörterbuch der frühchristlichen Kunst und Archäologie. Mit einem Anhang altgriechischer Fachwörter und 100 Abbildungen. 1. Auflage. Reclam, Stuttgart 2001, ISBN 978-3-15-008633-9 , Seite 134"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kymation","id":"dd7c2b3173a265"},"006b-0079:7f32f260ec5bf5":{"word":"Kyklop","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ky·klop","de-DE":"Ky·klop"},"forms":[{"form":"Kyklop","tags":["Nominativ","Singular"]},{"form":"Zyklop","tags":["variant"]},{"form":"Kyklopen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"einäugiger Riese aus der griechischen Mythologie"}],"synonyms":["Einäugiger","Zyklop"],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Kyklop","id":"7f32f260ec5bf5"},"006b-0079:ae89fd2c89bed6":{"word":"Kyma","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Kyma","de-DE":"Kyma"},"forms":[{"form":"Kyma","tags":["Nominativ","Singular"]},{"form":"Kymas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"ein antikes, friesartiges Ornament in Form einer Zier- oder Schmuckleiste, das in den drei klassischen Erscheinungsformen „dorisch“, „ionisch“ und „lesbisch“ vorkommt"}],"synonyms":[],"origins":["von griechisch: κῦμα (kỹma) entlehnt, wörtlich:Welle; vergleiche Kymation"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyma","id":"ae89fd2c89bed6"},"006b-0079:06e51aaeab1722":{"word":"Kyritz","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ky·ritz","de-DE":"Ky·ritz"},"forms":[{"form":"Kyritz’","tags":["Genitiv","Singular"]},{"form":"des Kyritz","tags":["Genitiv","Singular"]},{"form":"(das) Kyritz","tags":["Nominativ","Singular"]},{"form":"(dem) Kyritz","tags":["Dativ","Singular"]}],"senses":[{"definition":"eine Stadt in Brandenburg, Deutschland"}],"synonyms":[],"origins":[],"examples":[{"text":"Kyritz liegt in Deutschlands Osten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyritz","id":"06e51aaeab1722"},"006b-0079:e06131f74f86df":{"word":"Kyllburg","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Kyll·burg","de-DE":"Kyll·burg"},"forms":[{"form":"Kyllburgs","tags":["Genitiv","Singular"]},{"form":"des Kyllburg","tags":["Genitiv","Singular"]},{"form":"des Kyllburgs","tags":["Genitiv","Singular"]},{"form":"(das) Kyllburg","tags":["Nominativ","Singular"]},{"form":"(dem) Kyllburg","tags":["Dativ","Singular"]}],"senses":[{"definition":"eine Stadt in Rheinland-Pfalz, Deutschland"}],"synonyms":[],"origins":[],"examples":[{"text":"Kyllburg liegt in Deutschlands Südwesten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyllburg","id":"e06131f74f86df"},"006b-0079:a1da5e644526f9":{"word":"Kyrilliza","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·ril·li·za","de-DE":"Ky·ril·li·za"},"forms":[{"form":"Kirillica","tags":["variant"]},{"form":"Kyrilliza","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Alphabet, das kurz nach der Glagoliza im 10. Jahrhundert in Anlehnung an die griechische Unziale zur Verschriftlichung des Altkirchenslawischen entwickelt wurde und heute in einer vereinfachten Form für verschiedene Sprachen in Europa und Asien verwendet wird, darunter Russisch, Bulgarisch, Ukrainisch und andere"}],"synonyms":["Asbuka","kyrillisches Alphabet"],"origins":["Entlehnung aus dem gleichbedeutenden russischen кириллица (kirillica^☆) ^(→ ru)"],"examples":[{"text":"Von der serbischen Kyrilliza unterscheidet es sich durch die andere Form der Buchstaben ѓ (serbisch ђ bzw. đ in Lateinschrift) und ќ (serbisch ћ bzw. ć) sowie durch den zusätzlichen Buchstaben ѕ (der den im Serbischen nicht existierenden Laut [dz] wiedergibt).","reference":"Wikipedia-Artikel „Mazedonische Sprache“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Kyrilliza","id":"a1da5e644526f9"},"006b-0079:816d5ec1552650":{"word":"Kyrie eleison","partOfSpeech":"Interjektion","gender":"","hyphenation":{"de-CH":"Ky·rie elei·son","de-DE":"Ky·rie elei·son"},"forms":[{"form":"Kyrieleis","tags":["alternative"]}],"senses":[{"definition":"Bittruf zu Beginn einer Messe oder des Gottesdienstes, der gebetet oder gesungen wird"}],"synonyms":[],"origins":["von mittelgriechisch Κύριε ἐλέησον (Umschrift DIN 31634: Kýrie eléēson) „Herr, erbarme dich!“"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyrie eleison","id":"816d5ec1552650"},"006b-0079:0549d26223fa49":{"word":"Kyrieleis","partOfSpeech":"Interjektion","gender":"","hyphenation":{"de-CH":"Ky·rie·l·eis","de-DE":"Ky·rie·l·eis"},"forms":[{"form":"Kyrie eleison","tags":["alternative"]}],"senses":[{"definition":"Bittruf zu Beginn einer Messe oder des Gottesdienstes, der gebeten oder gesungen wird"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyrieleis","id":"0549d26223fa49"},"006b-0079:ed4567c84c72ad":{"word":"Kyrieeleison","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ky·rieelei·son","de-DE":"Ky·rieelei·son"},"forms":[{"form":"Kyrieeleison","tags":["Nominativ","Singular"]},{"form":"Kyrieeleisons","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Bittruf bei Messen und Gottesdiensten"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyrieeleison","id":"ed4567c84c72ad"},"006b-0079:72ded438888043":{"word":"Kyniker","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ky·ni·ker","de-DE":"Ky·ni·ker"},"forms":[{"form":"Kyniker","tags":["Nominativ","Singular"]},{"form":"Kynikern","tags":["Dativ","Plural"]},{"form":"Kynikers","tags":["Genitiv","Singular"]},{"form":"Kynikerin","tags":["feminine"]}],"senses":[{"definition":"Anhänger des Kynismus; Person, die einer antiken Philosophenschule angehört, die Bedürfnislosigkeit von ihren Schülern forderte"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Kyniker betonten, daß wirkliches Glück nicht von Äußerlichkeiten wie materiellem Luxus, politischer Macht oder guter Gesundheit abhänge.“","reference":"Jostein Gaarder: Sofies Welt. Roman über die Geschichte der Philosophie. 6. Auflage. dtv, München 2000, ISBN 3423125551, Seite 158"},{"text":"„Peregrin hatte allerlei in dieser Hinsicht durchprobiert und durchgemacht, und das Ende seines Lebens war eine öffentliche Selbstverbrennung bei den Olympischen Spielen des Jahres 165, angeblich um zu demonstrieren, dass ein Kyniker keinen Schmerz fürchte und, wer an ein glückliches Jenseits glaube, den Tod nicht zu fürchten habe.“","reference":"Jan Philipp Reemtsma, in Zusammenarbeit mit Fanny Esterházy: Christoph Martin Wieland. Die Erfindung der modernen deutschen Literatur. C. H. Beck, München 2023, ISBN 978-3-406-80070-2, Seite 520 f."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyniker","id":"72ded438888043"},"006b-0079:30d861efbbba36":{"word":"Kynikerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·ni·ke·rin","de-DE":"Ky·ni·ke·rin"},"forms":[{"form":"Kyniker","tags":["masculine"]},{"form":"Kynikerin","tags":["Nominativ","Singular"]},{"form":"Kynikerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Anhängerin des Kynismus; weibliche Person, die einer antiken Philosophenschule angehört, die Bedürfnislosigkeit von ihren Schülern forderte"}],"synonyms":[],"origins":[],"examples":[{"text":"Diese Kynikerin musste auch dazu etwas sagen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kynikerin","id":"30d861efbbba36"},"006b-0079:bbcfbb002aa159":{"word":"Kyoto","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Kyo·to","de-DE":"Kyo·to"},"forms":[{"form":"Kioto","tags":["alternative"]},{"form":"Kyōto","tags":["alternative"]},{"form":"Kyotos","tags":["Genitiv","Singular"]},{"form":"des Kyoto","tags":["Genitiv","Singular"]},{"form":"des Kyotos","tags":["Genitiv","Singular"]},{"form":"(das) Kyoto","tags":["Nominativ","Singular"]},{"form":"(dem) Kyoto","tags":["Dativ","Singular"]}],"senses":[{"definition":"japanische Stadt im Südwesten Honshus mit ca. 1,4 Millionen Einwohnern, Verwaltungssitz der gleichnamigen Präfektur"},{"definition":"das Kyoto-Protokoll, ein Abkommen zum Klimaschutz"}],"synonyms":[],"origins":[],"examples":[{"text":"Kyoto der Hort der japanischen Teetradition.","reference":""},{"text":"Es scheint, Japan habe aus Kyoto eine Lehre gezogen.","reference":"Quelle: www.nachrichten.at, 2011-01-15; nach Uni Leipzig: Wortschatz-Portal „Kyoto“"},{"text":"„Unter Kyoto kann ein Betrieb entscheiden, keine emissionsvermeidenden Maßnahmen zu setzen und stattdessen ausreichend Emissionszertifikate zu kaufen.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 12. Dezember 2017."}],"idioms":[],"collocations":[],"derivations":["Kyotoer"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyoto","id":"bbcfbb002aa159"},"006b-0079:a4547365864921":{"word":"Kymrisch","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Kym·risch","de-DE":"Kym·risch"},"forms":[{"form":"das Kymrische","tags":["Nominativ","Singular"]},{"form":"(das) Kymrisch","tags":["Nominativ","Singular"]},{"form":"(dem) Kymrisch","tags":["Dativ","Singular"]},{"form":"(des) Kymrisch","tags":["Genitiv","Singular"]},{"form":"dem Kymrischen","tags":["Dativ","Singular"]},{"form":"des Kymrischen","tags":["Genitiv","Singular"]},{"form":"(des) Kymrischs","tags":["Genitiv","Singular"]}],"senses":[{"definition":"in Wales gesprochene, zur keltischen Sprachfamilie gehörende Sprache"}],"synonyms":["Walisisch"],"origins":[],"examples":[{"text":"„Die keltischen Sprachen heute teilen sich auf in die goidelische Sprachgruppe mit den Sprachen Irisch, Gälisch und Manx und die britannische Sprachgruppe mit den Sprachen Kymrisch, Kumbrisch, Kornisch und Bretonisch.“","reference":"Ulrike Peters: Kelten. Ein Schnellkurs. DuMont, Köln 2011, ISBN 978-3-8321-9319-5 , Seite 150."},{"text":"„Wenn das Belegmaterial reich genug ist, wird lediglich Hethitisch, Altindisch, Tocharisch, Griechisch, Lateinisch, Altirisch (gegebenenfalls modernes Kymrisch), Litauisch und Altkirchenslavisch aufgeführt; andere Sprachen nur, wenn sie besondere Aufschlüsse bieten oder das Material der regelmäßig geführten Sprachen versagt.“","reference":"Friedrich Kluge, bearbeitet von Elmar Seebold: Etymologisches Wörterbuch der deutschen Sprache. 24., durchgesehene und erweiterte Auflage. Walter de Gruyter, Berlin/New York 2001, ISBN 978-3-11-017473-1, DNB 965096742 , Seite XI."}],"idioms":[],"collocations":[],"derivations":["kymrisch"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Kymrisch","id":"a4547365864921"},"006b-0079:099f6402583a84":{"word":"Kyu","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Kyu","de-DE":"Kyu"},"forms":[{"form":"Kyu","tags":["Nominativ","Singular"]},{"form":"Kyus","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Rangstufe für Anfänger, die in insgesamt Leistungsstufen unterteilt ist und an der Farbe des Gürtels erkennbar ist"}],"synonyms":[],"origins":["Entlehnung aus dem japanischen 級 (きゅう, kyū) ^(→ ja)"],"examples":[{"text":"Sie hat den vierten Kyu.","reference":""},{"text":"Er hat die Prüfung zum zweiten Kyu abgelegt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyu","id":"099f6402583a84"},"006b-0079:9c6fa6836de56b":{"word":"Kyudo","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Kyu·do","de-DE":"Kyu·do"},"forms":[{"form":"Kyudo","tags":["Nominativ","Singular"]},{"form":"Kyudos","tags":["Genitiv","Singular"]}],"senses":[{"definition":"japanische Kunst des Bogenschießens, bei der auf ein Ziel in 28 Meter Entfernung geschossen wird"}],"synonyms":[],"origins":["Entlehnung aus dem japanischen 弓道 (きゅうどう, kyūdō) ^(→ ja)"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyudo","id":"9c6fa6836de56b"},"006b-0079:0fe644aa8895b8":{"word":"Kyushu","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ky·us·hu","de-DE":"Ky·us·hu"},"forms":[{"form":"Kyushus","tags":["Genitiv","Singular"]},{"form":"des Kyushu","tags":["Genitiv","Singular"]},{"form":"des Kyushus","tags":["Genitiv","Singular"]},{"form":"(das) Kyushu","tags":["Nominativ","Singular"]},{"form":"(dem) Kyushu","tags":["Dativ","Singular"]}],"senses":[{"definition":"südlichste der vier Hauptinseln Japans"}],"synonyms":[],"origins":[],"examples":[{"text":"Kyushu ist die drittgrößte Insel Japans.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyushu","id":"0fe644aa8895b8"},"006b-0079:dab1ecff390e18":{"word":"Kybernetiker","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ky·ber·ne·ti·ker","de-DE":"Ky·ber·ne·ti·ker"},"forms":[{"form":"Kybernetiker","tags":["Nominativ","Singular"]},{"form":"Kybernetikern","tags":["Dativ","Plural"]},{"form":"Kybernetikers","tags":["Genitiv","Singular"]},{"form":"Kybernetikerin","tags":["feminine"]}],"senses":[{"definition":"wissenschaftlicher Fachmann auf dem Gebiet der Kybernetik"}],"synonyms":[],"origins":["Ableitung von Kybernetik mit dem Ableitungsmorphem -er"],"examples":[{"text":"Gregory Bateson war ein bekannter Kybernetiker des 20. Jahrhunderts.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kybernetiker","id":"dab1ecff390e18"},"006b-0079:803e87cd3dae7b":{"word":"Kyphose","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·pho·se","de-DE":"Ky·pho·se"},"forms":[{"form":"Kyphose","tags":["Nominativ","Singular"]},{"form":"Kyphosen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"nach hinten (dorsal) konvexe Krümmung der Wirbelsäule"}],"synonyms":["Hexenbuckel","Witwenbuckel"],"origins":["Neuwort (Neologismus), gebildet aus altgriechisch κυφός (kyphos^☆) ^(→ grc) „gebückt, gekrümmt“ und dem Wortbildungselement -ose „(krankhafter) Vorgang, Zustand; Erkrankung“"],"examples":[{"text":"Natürlicherweise kommt Kyphose im Brustbereich vor und am unteren Ende der Wirbelsäule als eine kleine Kyphose.","reference":"Kyphose (Rundrücken). primomedico.com, abgerufen am 7. April 2023."},{"text":"„Bei einer verstärkten Kyphose bleibt eine Restkrümmung bestehen.“","reference":"Wolfgang Rüdiger Hepp, Hans Ulrich: Orthopädisches Diagnostikum. Georg Thieme Verlag, 2004, ISBN 3133240072, Seite 79"}],"idioms":[],"collocations":[],"derivations":["Hyperkyphose","kyphotisch"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Kyphose","id":"803e87cd3dae7b"},"006b-0079:0b30974ad09311":{"word":"Kynomartyrion","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ky·n·om·ar·ty·ri·on","de-DE":"Ky·n·om·ar·ty·ri·on"},"forms":[{"form":"Kynomartyria","tags":["Nominativ","Plural"]},{"form":"Kynomartyrion","tags":["Nominativ","Singular"]},{"form":"Kynomartyrions","tags":["Genitiv","Singular"]}],"senses":[{"definition":"rituelle Opferung eines Hundes, zum Beispiel in Form der Hundeschaukel, Hundeschaukel"}],"synonyms":[],"origins":["griechisch kyno ^(→ gr) = Hund; griechisch martýrion ^(→ gr) = (Blut)zeugnis"],"examples":[{"text":"Das Kynomartyrion - Die Hundefolter wird in der Karnevalszeit durchgeführt, und zwar mit deutlichem Kulminationspunkt gegen Ende der Periode, und steht in vagem Zusammenhang mit der Existenz kynokephaler Dämonen.","reference":"Fehlender Parameter (Hilfe) Abgerufen am 14. Dezember 2016."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kynomartyrion","id":"0b30974ad09311"},"006b-0079:b48cee7661c004":{"word":"Kynologie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·no·lo·gie","de-DE":"Ky·no·lo·gie"},"forms":[{"form":"Kynologie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Lehre von Rassen, Zucht, Pflege, Verhalten, Erziehung und Krankheiten der Haushunde"}],"synonyms":[],"origins":["aus altgriechisch κύων (kyōn^☆) ^(→ grc) „Hund“ und dem gebundenen Lexem -logie"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kynologie","id":"b48cee7661c004"},"006b-0079:14c57ea1510920":{"word":"Kymographie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·mo·gra·phie","de-DE":"Ky·mo·gra·phie"},"forms":[{"form":"Kymografie","tags":["alternative"]},{"form":"Kymographie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Verfahren, mit dem Röntgenbilder von sich bewegenden Organen aufgenommen werden"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Kymographie wird zum Beispiel angewendet, um Bewegungen des Herzes darzustellen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kymographie","id":"14c57ea1510920"},"006b-0079:48578cf17cc826":{"word":"Kyudoka","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Kyu·do·ka","de-DE":"Kyu·do·ka"},"forms":[{"form":"Kyudoka","tags":["Nominativ","Singular"]},{"form":"Kyudokas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Person, die Kyudo betreibt"},{"definition":"weibliche Person, die Kyudo betreibt"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyudoka","id":"48578cf17cc826"},"006b-0079:c8f38be67bc122":{"word":"Kykladen","partOfSpeech":"Toponym","gender":"","hyphenation":{"de-CH":"Ky·kla·den","de-DE":"Ky·kla·den"},"forms":[{"form":"Kykladen","tags":["Nominativ","Plural"]},{"form":"Zykladen","tags":["variant"]}],"senses":[{"definition":"zu Griechenland gehörige Inselgruppe im Ägäischen Meer"}],"synonyms":[],"origins":["Das Wort Kykladen heißt übersetzt „Ringinseln“, da das heilige Eiland Delos im Zentrum der Inselgruppe liegt"],"examples":[{"text":"Die Kykladen liegen südöstlich von Athen, östlich des Peleponnes und nördlich von Kreta.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kykladen","id":"c8f38be67bc122"},"006b-0079:466ad63825a098":{"word":"kynisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ky·nisch","de-DE":"ky·nisch"},"forms":[{"form":"cynisch","tags":["obsolete"]},{"form":"kynisch","tags":["Positiv"]},{"form":"kynische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"kynischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"kynischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"kynischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"kynisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist kynisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist kynisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist kynisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind kynisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die Philosophie der Kyniker betreffend"}],"synonyms":["aggressiv","aristophanisch","beißend","bissig","boshaft","bösartig","böse","gallig","gehässig","gemein","giftig","inzisiv","kaustisch","polemisch","sardonisch","sarkastisch","satirisch","scharfzüngig","schneidend","schnippisch","schwarzhumorig","spitz","spitzzüngig","spöttisch","zynisch","ätzend"],"origins":["Ableitung zum Stamm des Wortes Kyniker mit dem Ableitungsmorphem -isch"],"examples":[{"text":"„Die ewige Wiederkehr des Gleichen, Nietzsches subversivster Gedanke - kosmologisch haltlos, doch kulturmorphologisch fruchtbar -, trifft ein Wiedervordringen kynischer Motive, die in der römischen Kaiserzeit zuletzt, ein wenig auch in der Renaissance, sich zu bewußtem Leben entfaltet hatten.“","reference":"Sloterdijk, Peter: Kritik der zynischen Vernunft Bd. 1, Frankfurt: Suhrkamp 1983, S. 10."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"kynisch","id":"466ad63825a098"},"006b-0079:209073714e1b2f":{"word":"Kyklader","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Ky·kla·der","de-DE":"Ky·kla·der"},"forms":[{"form":"Kyklader","tags":["Nominativ","Singular"]},{"form":"Kykladern","tags":["Dativ","Plural"]},{"form":"Kykladers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Bewohner der griechischen Inselgruppe der Kykladen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Bis auf zahlreiche Handelsstützpunkte scheinen die Kyklader und Minoer keine Kolonien besessen zu haben.“","reference":"Volker J. Dietrich: Die Wiege der abendländischen Kultur und die minoische Katastrophe – ein Vulkan verändert die Welt. 2004, ISSN 0379-1327, Seite 33"},{"text":"„Zeugnisse einer Siegesparade mit Kriegern und Kapitänen zur See deuten nicht nur auf Handelsschiffe der Kyklader und Minoer, sondern auch auf die Herrscher der Ägäis während eines Zeitraumes von mehreren Jahrhunderten.“","reference":"Naturforschende Gesellschaft in Zürich (Herausgeber): Neujahrsblatt, Ausgabe 207. Zürich 2004, Seite 37"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyklader","id":"209073714e1b2f"},"006b-0079:afca9c7bbe359b":{"word":"Kybernetikerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·ber·ne·ti·ke·rin","de-DE":"Ky·ber·ne·ti·ke·rin"},"forms":[{"form":"Kybernetiker","tags":["masculine"]},{"form":"Kybernetikerin","tags":["Nominativ","Singular"]},{"form":"Kybernetikerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Wissenschaftlerin die auf dem Gebiet der Kybernetik tätig ist"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Kybernetiker mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kybernetikerin","id":"afca9c7bbe359b"},"006b-0079:7f75eca1ee42c4":{"word":"Kyffhäuser","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Kyff·häu·ser","de-DE":"Kyff·häu·ser"},"forms":[{"form":"Kyffhäuser","tags":["Nominativ","Singular"]},{"form":"Kyffhäusers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Mittelgebirge im Südosten des Harzes"}],"synonyms":["Kyffhäusergebirge"],"origins":[],"examples":[{"text":"„Im 25. Gründungsjahr des Reiches wurde auf dem Kyffhäuser ein riesenhaftes Denkmal eingeweiht […].“","reference":"Knut Görich: Die Staufer. In: G/Geschichte. Nummer 3/2017, ISSN 1617-9412, Seite 19."}],"idioms":[],"collocations":[],"derivations":["Kyffhäuserkreis"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Kyffhäuser","id":"7f75eca1ee42c4"},"006b-0079:7ae093f3f880f4":{"word":"Kyrenaika","partOfSpeech":"Toponym","gender":"die","hyphenation":{"de-CH":"Ky·re·nai·ka","de-DE":"Ky·re·nai·ka"},"forms":[{"form":"Cyrenaika","tags":["variant"]},{"form":"Kyrenaika","tags":["Nominativ","Singular"]}],"senses":[{"definition":"historische Landschaft in Nordafrika"}],"synonyms":["Cyrenaika"],"origins":[],"examples":[{"text":"„An der Küste der Kyrenaika treffen Odysseus und seine Leute auf die Lotophagen, die ihren Namen von einer Droge haben, die vergessen macht.“","reference":"Berthold Seewald: Die Realität hinter dem genialen Helden der Antike. In: Welt Online. 17. Februar 2018, ISSN 0173-8437 (URL, abgerufen am 6. April 2021) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Kyrenaika","id":"7ae093f3f880f4"},"006b-0079:370056ef2e9c75":{"word":"kykladisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ky·kla·disch","de-DE":"ky·kla·disch"},"forms":[{"form":"kykladisch","tags":["Positiv"]},{"form":"kykladische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"kykladischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"kykladischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"kykladischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"kykladisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist kykladisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist kykladisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist kykladisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind kykladisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die griechische Inselgruppe der Kykladen oder ihre Bewohner betreffend, zu ihnen gehörend, von ihnen stammend"}],"synonyms":[],"origins":[],"examples":[{"text":"„Auf vielen farbigen Fresken erscheinen die minoischen und kykladischen Frauen als stolze Herrinnen und Gebieterinnen.“","reference":"Volker J. Dietrich: Die Wiege der abendländischen Kultur und die minoische Katastrophe – ein Vulkan verändert die Welt. 2004, ISSN 0379-1327, Seite 42"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"kykladisch","id":"370056ef2e9c75"},"006b-0079:7b6b8ca779da6a":{"word":"kybernetisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ky·ber·ne·tisch","de-DE":"ky·ber·ne·tisch"},"forms":[{"form":"kybernetisch","tags":["Positiv"]},{"form":"kybernetische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"kybernetischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"kybernetischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"kybernetischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"kybernetisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist kybernetisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist kybernetisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist kybernetisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind kybernetisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"auf die Kybernetik (Wissenschaft, die sich mit der Selbststeuerung von Systemen beschäftigt) oder ihre Erkenntnisse bezogen"}],"synonyms":[],"origins":["vom Substantiv Kybernetik"],"examples":[{"text":"Klassisches Controlling basiert auf der Idee einer Steuerung durch einen kybernetischen Regelkreis.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"kybernetisch","id":"7b6b8ca779da6a"},"006b-0079:6d8b10ff4ca69c":{"word":"kyphotisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"ky·pho·tisch","de-DE":"ky·pho·tisch"},"forms":[{"form":"kyphotisch","tags":["Positiv"]},{"form":"kyphotische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"kyphotischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"kyphotischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"kyphotischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"kyphotisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist kyphotisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist kyphotisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist kyphotisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind kyphotisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"in der Art einer Kyphose verkrümmt; an Kyphose leidend"}],"synonyms":[],"origins":["Derivation (Ableitung) vom Substantiv Kyphose mit dem Suffix -otisch"],"examples":[{"text":"Dabei befindet sich der Oberkörper in einer kyphotischen Verspannung, d.h. der obere Rücken ist mehr oder weniger gerundet.","reference":"Nackenfehlhaltungen. pohltherapie.de, abgerufen am 8. April 2023."},{"text":"Die Wirbelsäule ist im lumbalen Bereich kyphotisch, wobei die aktive Aufrichtung bei Muskelhypotonie nicht gelingt.","reference":"Die motorische Schulreife zu Hause und in der Therapie fördern. muskelhypotonie.de, 0.001989060169070114, abgerufen am 8. April 2023."},{"text":"Wenn eine ältere Frau (und immer häufiger auch ältere Männer) mit kyphotisch verkrümmtem und verkürztem Oberkörper schmerzgeplagt vor uns steht, ist die Diagnose \"Osteoporose\" eindeutig … zu spät.","reference":"Martin Runge: Osteoporose - spät erkannt, selten behandelt. www.osd-ev.org, 6. Januar 2023, abgerufen am 8. April 2023."},{"text":"Eines dieser Muster ist die Kombination einer starken Hohlkreuzbildung in der Lendenwirbelsäule mit einer starken kyphotischen Krümmung der Brustwirbelsäule (…).","reference":"Claudia Spahn: Musikergesundheit in der Praxis. www.legimi.pl, 2015, abgerufen am 8. April 2023 (Buchbesprechung)."},{"text":"Ist die Brustwirbelsäule jedoch zu stark kyphotisch gekrümmt – wie beim »Rundrücken« –, so steht das Schulterblatt am Rücken ab und die Schultern »fallen nach vorn«.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"kyphotisch","id":"6d8b10ff4ca69c"},"006b-0079:80376128757820":{"word":"Kybele","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Ky·be·le","de-DE":"Ky·be·le"},"forms":[{"form":"Cybele","tags":["alternative"]},{"form":"Kybeles","tags":["Genitiv","Singular"]},{"form":"der Kybele","tags":["Genitiv","Singular"]},{"form":"(der) Kybele","tags":["Dativ","Singular"]},{"form":"(die) Kybele","tags":["Nominativ","Singular"]}],"senses":[{"definition":"aus Phrygien stammende Göttin"}],"synonyms":[],"origins":[],"examples":[{"text":"„Anchester war einst das Lager der dritten Legion des Augustus gewesen, wovon viele Überreste zeugen, und es hieß, dass der Tempel der Kybele prächtig gewesen sei und mit Anbetern zum Bersten gefüllt, die auf Geheiß eines phrygischen Priesters unaussprechliche Zeremonien vollführten.“","reference":"H.P. Lovecraft: Die Ratten im Gemäuer. In: Das Gesamtwerk: Sämtliche Erzählungen und Zusammenarbeiten. Festa, Leipzig 2020, ISBN 978-3-865-52882-7, Seite 356 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kybele","id":"80376128757820"},"006b-0079:710b40ff60b646":{"word":"Kyjiw","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Ky·jiw","de-DE":"Ky·jiw"},"forms":[{"form":"Kiew","tags":["variant"]},{"form":"Kyiv","tags":["alternative"]},{"form":"Kyïv","tags":["alternative","rare"]},{"form":"Kyjiv","tags":["alternative"]},{"form":"Kyjiws","tags":["Genitiv","Singular"]},{"form":"des Kyjiw","tags":["Genitiv","Singular"]},{"form":"des Kyjiws","tags":["Genitiv","Singular"]},{"form":"(das) Kyjiw","tags":["Nominativ","Singular"]},{"form":"(dem) Kyjiw","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hauptstadt der Ukraine sowie Hauptort und Verwaltungssitz der Oblast Kyjiw"}],"synonyms":[],"origins":["transliterierte Entlehnung des ukrainischen Київ (Kyïv^☆) ^(→ uk)"],"examples":[{"text":"Kyjiw liegt am Dnipro.","reference":""},{"text":"„Leider kommt es in der SZ immer wieder vor, daß Sie die ukrainische Sprache weiter russifizieren. Die ukrainische Hauptstadt heißt Kyjiw und nicht Kiew, die Währung Hrywna und nicht Griwna.“","reference":"Jurij Ciurak: Hamburg ist nicht Gamburg. In: Süddeutsche Zeitung. Nummer 49, 1. März 1999, ISSN 0174-4917, Seite 9 (Leserbrief) ."},{"text":"„Berduta lud zu einer Reise von Kyjiw bis Saporischschja, ihrer Heimatstadt, ein, dabei vermittelte sie geschickt wichtige Daten über die Ukraine.“","reference":"Liebevoller Blick durch die Kamera. In: Allgemeine Zeitung. 5. Juni 2012 ."},{"text":"„Auch bei den Flügen aus Moskau, Kyjiw, London und Dublin ist der Anteil der Skitouristen traditionell hoch.“","reference":"Neue Ziele in Jordanien und Ägypten im Winterflugplan. In: Schwäbische Zeitung. 25. Oktober 2019, Seite 25 ."},{"text":"„Weiter geht es gegen 13 Uhr mit dem ukrainischen Intercity Richtung Kyjiw, das der Schnellzug am späten Abend erreicht.“","reference":"Marco Zschieck: Berlin, Wien, Lemberg, Sibiu. In: taz.die tageszeitung. Nummer 12259, 13. Juni 2020, ISSN 1434-4459, Seite 44 (taz Print Archiv-URL, abgerufen am 24. Februar 2024) ."},{"text":"„Die heute angekündigte Ausgangssperre für Kyjiw wurde nun auf die gesamte Oblast ausgeweitet. […] In Kyjiw und der Oblast Kyjiw lebten vor Beginn des Krieges circa 4,75 Millionen Menschen. […] Bürgermeister Klitschko fordert Kyjiws Bürger via Telegram dazu auf, sich auf eine längere Ausgangssperre vorzubereiten.“","reference":"Daniela Krenn, Lilly Graschl, Alexander Fürniß, Anja Köneke, Benjamin Fredrich, Cornelia Schimek, Iris Becker, Janina Kiekebusch, Jonathan Dehn, Juli Katz, Ole Kracht, Sebastian Haupt, Tim Ehlers, Tabea Stock und Judith Schneider: Liveblog zum Krieg in der Ukraine. In: KATAPULT. 17. März 2022 (URL, abgerufen am 24. Februar 2024) ."},{"text":"„Auf einmal richtete sich Nadijka auf und sagte mit ausgestrecktem Arm: »Da, bald sind wir in Kyjiw.« Kyjiw! Das war die große Stadt, in der er studieren und leben würde.“","reference":"Walerjan Pidmohylnyj: Die Stadt. Erste Auflage. Guggolz Verlag, Berlin 2022 (Originaltitel: Місто, übersetzt von Alexander Kratochvil, Lukas Joura, Jakob Wunderwald und Lina Zalitok aus dem Ukrainischen), ISBN 978-3-945370-35-3, Seite 12 (ukrainische Originalausgabe 1928) ."}],"idioms":[],"collocations":[],"derivations":["Kyjiwer","kyjiwisch","Kyjiwerin"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyjiw","id":"710b40ff60b646"},"006b-0079:16824298e90f9f":{"word":"Kyiv","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Kyiv","de-DE":"Kyiv"},"forms":[{"form":"Kiew","tags":["variant"]},{"form":"Kyïv","tags":["alternative","rare"]},{"form":"Kyivs","tags":["Genitiv","Singular"]},{"form":"Kyjiv","tags":["alternative"]},{"form":"Kyjiw","tags":["alternative"]},{"form":"des Kyiv","tags":["Genitiv","Singular"]},{"form":"des Kyivs","tags":["Genitiv","Singular"]},{"form":"(das) Kyiv","tags":["Nominativ","Singular"]},{"form":"(dem) Kyiv","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hauptstadt der Ukraine sowie Hauptort und Verwaltungssitz der Oblast Kyiv"}],"synonyms":[],"origins":["transliterierte Entlehnung des ukrainischen Київ (Kyïv^☆) ^(→ uk)"],"examples":[{"text":"„Nach Kaiser Karl I. im Kriegsfrühjahr 1917 kam als regierender Besucher aus Wien erst wieder Vizekanzler Busek in den Vorort des einstigen Ostgalizien, der heutigen Westukraine – nach Lviv (russisch und polnisch Lvov, lateinisch Leopolis), das sich in seinem kulturellen Selbstverständnis von Kyiv (Kiew), Charkiv (Charkow) und Odessa aus vielerlei Gründen unterscheidet.“","reference":"Alte Habsburger-Toleranz, jüngste Hilfen. In: Die Presse. 6. Oktober 1992, ISSN 1563-5449, DNB 947702091 ."},{"text":"«Seit 1934 ist Kyiv anstelle von Charkow die Hauptstadt der Ukraine und zählt heute 2,8 Millionen Einwohner.»","reference":"Von Poznan bis Charkow: Die Austragungsstädte der Euro 2012 kurz vorgestellt. In: südostschweiz. 8. Februar 2010 ."}],"idioms":[],"collocations":[],"derivations":["Kyiver","kyivisch","Kyiverin"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyiv","id":"16824298e90f9f"},"006b-0079:6f03c4c466b50d":{"word":"Kyïv","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Kyïv","de-DE":"Kyïv"},"forms":[{"form":"Kiew","tags":["variant"]},{"form":"Kyiv","tags":["alternative"]},{"form":"Kyjiv","tags":["alternative"]},{"form":"Kyjiw","tags":["alternative"]},{"form":"Kyïvs","tags":["Genitiv","Singular"]},{"form":"des Kyïv","tags":["Genitiv","Singular"]},{"form":"des Kyïvs","tags":["Genitiv","Singular"]},{"form":"(das) Kyïv","tags":["Nominativ","Singular"]},{"form":"(dem) Kyïv","tags":["Dativ","Singular"]}],"senses":[{"definition":"Hauptstadt der Ukraine sowie Hauptort und Verwaltungssitz der Oblast Kyïv"}],"synonyms":[],"origins":["transliterierte Entlehnung des ukrainischen Київ (Kyïv^☆) ^(→ uk)"],"examples":[{"text":"«Bei der Mehrheit der Schweizer Bevölkerung wohl ziemlich ignoriert, gilt seit dem 11. Juni endlich das visumfreie Reisen in und durch Europa für ein Land, das sich wohl mehr als viele andere Länder als Teil Europas fühlt und dafür grosse Opfer auf sich genommen hat, nämlich für das Volk der Ukraine. Das ist sehr erfreulich, denn die Schikanen, die das Einholen eines Visums erforderte (persönliche Reise nach Kyïv[,] nichts per Post!) und die hohen Kosten, waren unerträglich für die meist finanziell nicht auf Rosen gebetteten Menschen aus diesem Land, wenn sie Verwandte oder Freunde in einem Land des Schengenraums, also auch in der Schweiz besuchen wollten.»","reference":"Visumpflicht für Ukraine. In: Basler Zeitung. 13. Juni 2017, Seite 16 ."}],"idioms":[],"collocations":[],"derivations":["Kyïver","kyïvisch","Kyïverin"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyïv","id":"6f03c4c466b50d"},"006b-0079:0ea60538f3b7fd":{"word":"Kyrie","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Ky·rie","de-DE":"Ky·rie"},"forms":[{"form":"Kyrie","tags":["Nominativ","Singular"]},{"form":"Kyries","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Bittruf zu Beginn einer Messe oder des Gottesdienstes, der gebetet oder gesungen wird (Kurzform von Kyrie eleison)"}],"synonyms":[],"origins":[],"examples":[{"text":"„Musiker und Chor interpretieren den barocken Komponisten Franz Biber beim Kyrie, Sanctus, Benedictus und beim Agnus Dei - den vier Texten, die seit 998 zu einem Requiem gehören.“","reference":"Marlies Emmerich: DEUTSCHLAND. Berliner Zeitung, 07.04.2005. Zitiert nach: DWDS Korpusbelege Berliner Zeitung (1994–2005)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyrie","id":"0ea60538f3b7fd"},"006b-0079:03483395f49497":{"word":"Kylltal","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Kyll·tal","de-DE":"Kyll·tal"},"forms":[{"form":"Kylltal","tags":["Nominativ","Singular"]},{"form":"Kylltals","tags":["Genitiv","Singular"]},{"form":"Kylltales","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Tal, in dem die Kyll fließt"}],"synonyms":[],"origins":["Determinativkompositum aus dem Hydronym Kyll und dem Substantiv Tal"],"examples":[{"text":"„Der Abstieg ins Kylltal wird vom Rauschen des Flusses begleitet, bevor es wieder bergauf geht.“","reference":"Julia Borsch: Wandern im idyllischen Kylltal. In: WochenSpiegel. Weiss-Verlag GmbH & Co. KG, 5. April 2024, abgerufen am 25. März 2026 (HTTPS)."},{"text":"„Wie geht es den Menschen im Kylltal ein Jahr nach der Flut?“","reference":"Katharina De Mos: Auf Spurensuche im Kylltal – „Das war kein Hochwasser, das war eine Katastrophe!“ (Fotos/Video). In: Trierischer Volksfreund Online. 7. Juli 2022 (URL, abgerufen am 25. März 2026) ."},{"text":"„Mit einem sagenhaften Blick ins Kylltal und die Waldeifel.“","reference":"Katharina Pfänder: Hauptstraße in St. Thomas. In: Südwestrundfunk. 12. Dezember 2012 (URL, abgerufen am 25. März 2026) ."},{"text":"„Im oberen Kylltal im deutsch-belgischen Grenzgebiet der Eifel liegt der urige Ort Kronenburg.“","reference":"Im Kylltal wird Kunst im Stall geboten. In: Rhein-Zeitung. Mittelrhein-Verlag GmbH, 15. Dezember 2016, abgerufen am 25. März 2026 (HTTPS)."},{"text":"„Der Wald des Kylltals liegt unter einem und die Zeit spielt hier oben keine Rolle.“","reference":"Die Burg Ramstein: Über 300 Jahre thront sie über dem Kylltal. In: Saarbrücker Zeitung. Saarbrücker Zeitung Medienhaus GmbH, 16. März 2024, abgerufen am 25. März 2026 (HTTPS)."}],"idioms":[],"collocations":[],"derivations":["Kylltalbahn","Kylltalbrücke","Kylltalsperre"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kylltal","id":"03483395f49497"},"006b-0079:988bbf2596b03e":{"word":"Kyll an der Kyll","partOfSpeech":"Wortverbindung","gender":"das","hyphenation":{"de-CH":"Kyll an der Kyll","de-DE":"Kyll an der Kyll"},"forms":[{"form":"Kylls an der Kyll","tags":["Genitiv","Singular"]},{"form":"des Kyll an der Kyll","tags":["Genitiv","Singular"]},{"form":"des Kylls an der Kyll","tags":["Genitiv","Singular"]},{"form":"(das) Kyll an der Kyll","tags":["Nominativ","Singular"]},{"form":"(dem) Kyll an der Kyll","tags":["Dativ","Singular"]}],"senses":[{"definition":"Ortsteil von Ittel, Welschbillig, Rheinland-Pfalz, Deutschland"}],"synonyms":[],"origins":["zusammengesetzt aus dem Toponym Kyll, der Präposition an, dem Artikel der und dem Hydronym Kyll"],"examples":[{"text":"Kyll an der Kyll liegt nordöstlich von Ittel.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyll an der Kyll","id":"988bbf2596b03e"},"006b-0079:3dbec2e25ed807":{"word":"Kynast","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Ky·nast","de-DE":"Ky·nast"},"forms":[{"form":"K.","tags":["Kurzform"]},{"form":"Kynast","tags":["Nominativ","Singular","masculine"]},{"form":"Künast","tags":["alternative"]},{"form":"Kienast","tags":["variant"]},{"form":"Kuenast","tags":["alternative"]},{"form":"Kynasts","tags":["Genitiv","Singular","masculine"]},{"form":"Kühnast","tags":["alternative"]},{"form":"Kiennast","tags":["variant"]},{"form":"Kuehnast","tags":["alternative"]},{"form":"dem Kynast","tags":["Dativ","Singular","masculine"]},{"form":"den Kynast","tags":["Akkusativ","Singular","masculine"]},{"form":"der Kynast","tags":["Nominativ","Singular","masculine"]},{"form":"des Kynast","tags":["Genitiv","Singular","masculine"]},{"form":"die Kynast","tags":["Nominativ","Singular","feminine"]},{"form":"den Kynasts","tags":["Dativ","Plural"]},{"form":"der Kynasts","tags":["Genitiv","Plural"]},{"form":"des Kynasts","tags":["Genitiv","Singular","masculine"]},{"form":"die Kynasts","tags":["Nominativ","Plural"]}],"senses":[{"definition":"deutschsprachiger Nachname, Familienname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Kynast ist ein Genie im Verkauf.","reference":""},{"text":"Herr Kynast wollte uns kein Interview geben.","reference":""},{"text":"Die Kynasts fahren heute nach Erfurt.","reference":""},{"text":"Der Kynast trägt nie die Pullover, die die Kynast ihm strickt.","reference":""},{"text":"Das kann ich dir aber sagen: „Wenn die Frau Kynast kommt, geht der Herr Kynast.“","reference":""},{"text":"Kynast kommt und geht.","reference":""},{"text":"Kynasts kamen, sahen und siegten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kynast","id":"3dbec2e25ed807"},"006b-0079:7c349bc37c6d5c":{"word":"Kyllburgweiler","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Kyll·burg·wei·ler","de-DE":"Kyll·burg·wei·ler"},"forms":[{"form":"Kyllburgweilers","tags":["Genitiv","Singular"]},{"form":"des Kyllburgweiler","tags":["Genitiv","Singular"]},{"form":"des Kyllburgweilers","tags":["Genitiv","Singular"]},{"form":"(das) Kyllburgweiler","tags":["Nominativ","Singular"]},{"form":"(dem) Kyllburgweiler","tags":["Dativ","Singular"]}],"senses":[{"definition":"Ortsgemeinde in Rheinland-Pfalz, Deutschland"}],"synonyms":[],"origins":[],"examples":[{"text":"Kyllburgweiler liegt nordöstlich von Bitburg.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyllburgweiler","id":"7c349bc37c6d5c"},"006b-0079:be2d6f3643f105":{"word":"Kyburz","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Ky·burz","de-DE":"Ky·burz"},"forms":[{"form":"K.","tags":["Kurzform"]},{"form":"Kyburz","tags":["Nominativ","Singular","masculine"]},{"form":"Kyburz’","tags":["Genitiv","Singular","masculine"]},{"form":"dem Kyburz","tags":["Dativ","Singular","masculine"]},{"form":"den Kyburz","tags":["Dativ","Plural"]},{"form":"der Kyburz","tags":["Nominativ","Singular","masculine"]},{"form":"des Kyburz","tags":["Genitiv","Singular","masculine"]},{"form":"die Kyburz","tags":["Nominativ","Singular","feminine"]},{"form":"den Kyburzes","tags":["Dativ","Plural"]},{"form":"der Kyburzes","tags":["Genitiv","Plural"]},{"form":"die Kyburzes","tags":["Nominativ","Plural"]},{"form":"den Kyburzens","tags":["Dativ","Plural"]},{"form":"der Kyburzens","tags":["Genitiv","Plural"]},{"form":"die Kyburzens","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Nachname, Familienname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Kyburz arbeitet als Medienpädagogin.","reference":""},{"text":"Herr Kyburz spricht fließend Albanisch.","reference":""},{"text":"Die Kyburzens fliegen heute nach Kuala Lumpur.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Kyburz","id":"be2d6f3643f105"}};
